import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react';

import {CancellablePromise} from '@gravity-ui/sdk';
import type {SelectOption} from '@gravity-ui/uikit';
import {getConfig} from '@gravity-ui/uikit';
import {useUpdateEffect} from 'react-use';

import type {AutocompleteProps} from '~/src/components/Select/Autocomplete';
import {Autocomplete} from '~/src/components/Select/Autocomplete';
import {useAutocomplete} from '~/src/components/Select/hooks/useAutocomplete';
import {useAutoFocus} from '~/src/hooks/useAutoFocus';
import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnQueueSelect} from './QueueSelect.classname';
import {defaultMessages} from './i18n';
import type {QueueInfo} from './types';
import {filterQueues} from './utils/filterQueues';
import {mapQueueToSelectItem} from './utils/mapQueueToSelectItem';
import {normalizeQueue} from './utils/normalizeQueue';
import {renderDisplayValue} from './utils/renderDisplayValue';

import './QueueSelect.scss';

export type QueueSelectProps = {
    queues?: QueueInfo[] | string[];
    defaultQueue?: QueueInfo | string;
    loading?: boolean;
    hideQueues?: ReadonlySet<string>;
    onSearch?:
        | ((text: string) => CancellablePromise<QueueInfo[]>)
        | ((text: string) => Promise<QueueInfo[]>);
    onChange?: (queue: QueueInfo) => void;
    onSelectClick?: () => void;
    initialEmpty?: boolean;
    withoutSuggest?: boolean;
    withValueIcon?: boolean;
    confirmUpdate?: () => Promise<{success: boolean}>;
    className?: string;
    withBorder?: boolean;
    size?: AutocompleteProps['size'];
    popupWidth?: AutocompleteProps['popupWidth'];
    error?: AutocompleteProps['error'];
    id?: AutocompleteProps['id'];
    withArrow?: AutocompleteProps['withArrow'];
    placeholder?: AutocompleteProps['placeholder'];
    renderFilter?: AutocompleteProps['renderFilter'];
    controlClassName?: AutocompleteProps['controlClassName'];
    disablePortal?: boolean;
};

export const QueueSelect = ({
    defaultQueue: propsDefaultQueue,
    queues: propsQueues,
    withoutSuggest,
    onChange,
    className,
    controlClassName,
    hideQueues,
    initialEmpty = false,
    withBorder = false,
    size = 'm',
    popupWidth,
    error,
    id,
    withValueIcon = false,
    withArrow,
    placeholder,
    disablePortal,
    confirmUpdate,
    onSelectClick,
    renderFilter,
    loading = false,
    onSearch,
}: QueueSelectProps) => {
    const [isOpen, setIsOpen] = useState(false);
    const [delayedIsOpen, setDelayedIsOpen] = useState(false);
    const popupContainerRef = useRef<HTMLDivElement>(null);
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    const handleOpenChange = useCallback(
        (value: boolean) => {
            if (value) {
                onSelectClick?.();
            }
            setIsOpen(value);
            requestAnimationFrame(() => {
                setDelayedIsOpen(value);
            });
        },
        [onSelectClick],
    );

    const fixedDefaultQueue: QueueInfo | undefined = useMemo(
        () => normalizeQueue(propsDefaultQueue),
        [propsDefaultQueue],
    );

    const fixedQueues: QueueInfo[] | undefined = useMemo(() => {
        if (!propsQueues) {
            return undefined;
        }
        return propsQueues.map((queue: QueueInfo | string) => normalizeQueue(queue)!);
    }, [propsQueues]);

    const filterQueue = useCallback(
        <TQueue extends QueueInfo | undefined>(queue: TQueue) => {
            if (hideQueues === undefined || queue === undefined) {
                return queue;
            }
            return (hideQueues.has(queue.key) ? undefined : queue) as TQueue;
        },
        [hideQueues],
    );

    const queues = useMemo(
        () => filterQueues(fixedQueues || [], hideQueues),
        [fixedQueues, hideQueues],
    );

    const defaultQueue =
        filterQueue(fixedDefaultQueue) || filterQueue(fixedQueues?.[0]) || filterQueue(queues[0]);

    useEffect(() => {
        if (!initialEmpty && Array.isArray(queues) && queues.length > 0) {
            onChange?.(defaultQueue ?? queues[0]!);
        }
    }, [onChange, queues, defaultQueue, initialEmpty]);

    const getQueues = useCallback(
        (searchText: string): CancellablePromise<QueueInfo[]> => {
            if (!onSearch) {
                return new CancellablePromise(Promise.resolve([]), () => {});
            }
            const innerPromise = onSearch(searchText);
            return new CancellablePromise(
                innerPromise.then((results) => filterQueues(results, hideQueues)),
                () => (innerPromise as CancellablePromise<QueueInfo[]>).cancel?.(),
            );
        },
        [onSearch, hideQueues],
    );

    const handleDisplayRender = useCallback(
        (value: SelectOption<QueueInfo>[]) =>
            renderDisplayValue(value, withValueIcon, placeholder, size),
        [placeholder, withValueIcon, size],
    );

    const {
        filteredItems: filteredQueues,
        handleFilterChange,
        isLoading: loadingQueues,
    } = useAutocomplete<QueueInfo[]>(getQueues);

    const [queue, setQueue] = useState<SelectOption<QueueInfo> | undefined>(
        initialEmpty || !defaultQueue
            ? undefined
            : mapQueueToSelectItem(
                  queues.find((item) => item.key === defaultQueue.key) ?? defaultQueue,
                  true,
              ),
    );

    const items = useMemo(() => {
        const queuesItems = filteredQueues ?? (queues.length ? [...queues] : [defaultQueue]);

        if (!filteredQueues && !queuesItems.some((q) => q?.key === defaultQueue?.key)) {
            queuesItems.unshift(defaultQueue);
        }

        return queuesItems
            .filter(Boolean)
            .map((queueItem) =>
                mapQueueToSelectItem(queueItem, queueItem?.key === queue?.data?.key),
            ) as SelectOption<QueueInfo>[];
    }, [defaultQueue, filteredQueues, queue?.data?.key, queues]);

    useUpdateEffect(() => {
        if (!initialEmpty && defaultQueue !== undefined && defaultQueue.key !== queue?.data?.key) {
            setQueue(mapQueueToSelectItem(defaultQueue, true));
            onChange?.(defaultQueue);
        }
    }, [defaultQueue, initialEmpty]);

    const handleSelectUpdate = useCallback(
        async (queueOption: SelectOption<QueueInfo>) => {
            const selectedQueue = {
                key: queueOption.value,
                showDefaultCreationForm: queueOption.data?.showDefaultCreationForm,
                enableCloneMoveForAll: queueOption.data?.enableCloneMoveForAll,
            };

            if (confirmUpdate) {
                const confirmResult = await confirmUpdate();
                if (!confirmResult.success) return;
            }

            onChange?.(selectedQueue);
            setQueue(mapQueueToSelectItem(queueOption.data, true));
        },
        [confirmUpdate, onChange],
    );

    useAutoFocus({
        containerRef: popupContainerRef,
        elementSelector: 'input',
        shouldFocus: delayedIsOpen,
    });

    const renderPopup = useCallback<NonNullable<AutocompleteProps['renderPopup']>>(
        ({renderList, renderFilter}) => (
            <div className={cnQueueSelect('popup-content')} ref={popupContainerRef}>
                {renderFilter()}
                {renderList()}
            </div>
        ),
        [],
    );

    return (
        <div className={cnQueueSelect({'with-border': withBorder, loading}, className)}>
            <Autocomplete
                disablePortal={disablePortal}
                filterPlaceholder={t('filter-placeholder')}
                className={cnQueueSelect('control')}
                popupClassName={cnQueueSelect('popup')}
                controlClassName={cnQueueSelect('control-block', controlClassName)}
                id={id}
                size={size}
                options={items}
                onFilterChange={withoutSuggest ? undefined : handleFilterChange}
                onUpdate={handleSelectUpdate}
                value={queue}
                loading={loading}
                loadingItems={loadingQueues}
                popupWidth={popupWidth}
                getOptionHeight={() => 48}
                error={error}
                withArrow={withArrow}
                placeholder={placeholder}
                renderFilter={renderFilter}
                controlProps={{'aria-label': t('select-queue')}}
                title={t('queue')}
                renderDisplayValue={handleDisplayRender}
                open={isOpen}
                onOpenChange={handleOpenChange}
                disableTooltip
                name="queue-input"
                renderPopup={renderPopup}
            />
        </div>
    );
};
